/**
 * 获取支付提供商统计 - 用于自动切换
 */
export async function getPaymentProviderStats(hours: number = 24) {
  try {
    const startTime = new Date(Date.now() - hours * 60 * 60 * 1000)

    const stats = await prisma.paymentOrder.groupBy({
      by: ['paymentProvider'],
      where: {
        createdAt: { gte: startTime },
        status: { in: ['pending', 'processing', 'completed'] }
      },
      _count: { id: true },
      _max: { createdAt: true }
    })

    return stats.map(stat => ({
      provider: stat.paymentProvider as PaymentProvider,
      count: stat._count.id,
      lastUsed: stat._max.createdAt || new Date(0)
    }))
  } catch (error) {
    console.error("❌ 获取支付统计失败:", error)
    return []
  }
}

/**
 * 获取过期订单
 */
export async function getExpiredOrders() {
  try {
    return await prisma.paymentOrder.findMany({
      where: {
        status: 'pending',
        expiredAt: { lt: new Date() }
      },
      include: { user: true }
    })
  } catch (error) {
    console.error("❌ 获取过期订单失败:", error)
    return []
  }
}

/**
 * 批量更新过期订单状态
 */
export async function markOrdersAsExpired(orderIds: string[]) {
  try {
    const result = await prisma.paymentOrder.updateMany({
      where: { id: { in: orderIds } },
      data: { 
        status: 'expired',
        updatedAt: new Date()
      }
    })

    console.log(`✅ 标记${result.count}个订单为过期`)
    return result
  } catch (error) {
    console.error("❌ 标记过期订单失败:", error)
    throw error
  }
}

/**
 * 获取订单统计数据
 */
export async function getOrderStatistics(userId?: string) {
  try {
    const whereClause = userId ? { userId } : {}

    const [total, completed, pending, failed] = await Promise.all([
      prisma.paymentOrder.count({ where: whereClause }),
      prisma.paymentOrder.count({ where: { ...whereClause, status: 'completed' } }),
      prisma.paymentOrder.count({ where: { ...whereClause, status: 'pending' } }),
      prisma.paymentOrder.count({ where: { ...whereClause, status: 'failed' } })
    ])

    const totalRevenue = await prisma.paymentOrder.aggregate({
      where: { ...whereClause, status: 'completed' },
      _sum: { amount: true }
    })

    return {
      total,
      completed,
      pending,
      failed,
      totalRevenue: totalRevenue._sum.amount || 0
    }
  } catch (error) {
    console.error("❌ 获取订单统计失败:", error)
    return {
      total: 0,
      completed: 0,
      pending: 0,
      failed: 0,
      totalRevenue: 0
    }
  }
}

# 🚀 NextAuth 从零到精通学习指南

## 🎯 为什么要学 NextAuth？

### **现实场景对比**

**场景：你有一个网站，10个页面需要登录才能访问**

#### **用 Supabase Auth（痛苦）**：
```javascript
// 😫 每个页面都要写这些代码（复制粘贴10次）
const [user, setUser] = useState(null)
const [loading, setLoading] = useState(true)

useEffect(() => {
  checkUser()
}, [])

const checkUser = async () => {
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) {
    // 😫 手动记录用户想去的页面
    localStorage.setItem('redirectTo', window.location.pathname)
    router.push('/login')
  } else {
    setUser(user)
  }
  setLoading(false)
}

if (loading) return <div>Loading...</div>  // 😫 每次都闪烁
if (!user) return null
```

#### **用 NextAuth（爽）**：
```javascript
// 🎉 一行代码搞定（写一次，用10次）
const { data: session } = useSession({ required: true })
// 自动检查登录、自动跳转、自动回来、无闪烁
```

## 📚 第1课：NextAuth 核心概念

### **NextAuth 是什么？**
- 🏠 **不是服务** - 是一个代码库，安装在你的项目里
- 🤖 **自动化管家** - 自动处理登录、登出、会话管理
- 🔌 **插件系统** - 支持各种登录方式（Google、GitHub、邮箱等）

### **核心文件结构**
```
src/
├── app/
│   ├── api/auth/[...nextauth]/route.ts  ← NextAuth 配置文件
│   └── login/page.tsx                   ← 登录页面
├── components/
│   └── LoginButton.tsx                  ← 登录按钮组件
└── middleware.ts                        ← 页面保护中间件
```

## 📚 第2课：基础配置（10分钟搞定）

### **步骤1：安装 NextAuth**
```bash
npm install next-auth
```

### **步骤2：创建配置文件**
```typescript
// src/app/api/auth/[...nextauth]/route.ts
import NextAuth from "next-auth"
import CredentialsProvider from "next-auth/providers/credentials"

const handler = NextAuth({
  providers: [
    // 邮箱密码登录
    CredentialsProvider({
      name: "credentials",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" }
      },
      async authorize(credentials) {
        // 这里连接你的 Supabase
        const { data, error } = await supabase.auth.signInWithPassword({
          email: credentials.email,
          password: credentials.password,
        })

        if (data.user) {
          return { id: data.user.id, email: data.user.email }
        }
        return null
      }
    })
  ],
  pages: {
    signIn: '/login',  // 自定义登录页面
  },
  callbacks: {
    async redirect({ url, baseUrl }) {
      // 🎉 自动跳转逻辑 - 登录后回到原页面
      return url.startsWith(baseUrl) ? url : baseUrl
    }
  }
})

export { handler as GET, handler as POST }
```

### **步骤3：创建登录页面**
```typescript
// src/app/login/page.tsx
"use client"
import { signIn } from "next-auth/react"
import { useState } from "react"

export default function LoginPage() {
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")

  const handleLogin = async () => {
    await signIn("credentials", { email, password })
    // 🎉 登录成功后自动跳转到用户想去的页面
  }

  return (
    <div>
      <input 
        type="email" 
        value={email} 
        onChange={(e) => setEmail(e.target.value)}
        placeholder="Email" 
      />
      <input 
        type="password" 
        value={password} 
        onChange={(e) => setPassword(e.target.value)}
        placeholder="Password" 
      />
      <button onClick={handleLogin}>Login</button>
    </div>
  )
}
```

## 📚 第3课：页面保护（1行代码）

### **保护单个页面**
```typescript
// src/app/dashboard/page.tsx
"use client"
import { useSession } from "next-auth/react"

export default function DashboardPage() {
  const { data: session } = useSession({ required: true })
  // 🎉 就这一行！自动检查登录状态
  // 未登录 → 自动跳转到 /login
  // 登录后 → 自动跳回这个页面

  return (
    <div>
      <h1>Dashboard</h1>
      <p>Welcome {session?.user?.email}</p>
    </div>
  )
}
```

### **保护多个页面（中间件）**
```typescript
// middleware.ts
import { withAuth } from "next-auth/middleware"

export default withAuth({
  pages: {
    signIn: "/login",
  },
})

export const config = {
  // 🎉 这些路径都需要登录
  matcher: ["/dashboard/:path*", "/profile/:path*", "/settings/:path*"]
}
```

## 📚 第4课：实际使用场景

### **场景1：用户信息显示**
```typescript
